-- DWA-M-820-1 M820-11 leistungswettbewerb_only: visible_when, description
INSERT INTO fields_archive_m820_wa SELECT f.* FROM fields f, worksheet_templates w, standards s
 WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-11' AND f.symbol = 'leistungswettbewerb_only' AND f.active
   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type)) = '7eb40a57f59b9dfebe8e1ac5f92e62fc'
   AND NOT EXISTS (SELECT 1 FROM fields_archive_m820_wa a WHERE a.id = f.id);
UPDATE fields f
   SET visible_when = $m$procurement_procedure != 'direktvergabe'$m$,
       description = $m$Bestätigt, dass kein reiner oder versteckter Preiswettbewerb für die Planungsleistung verwendet wurde. §8.7 (S. 34): Qualität ist „Teil des Leistungswettbewerbs, der gemäß §76 Abs. 1 VgV für Planungsleistungen zwingend vorgeschrieben ist.“ Bei Direktvergabe ausgeblendet (procurement_procedure = direktvergabe, M820-10): § 8.8 (S. 36): „Eine Direktvergabe ist eine Vergabe, bei der Verhandlungen mit nur einem Unternehmen geführt werden.“ Ohne Wettbewerb zwischen Bewerbern oder Bietern hat diese Angabe keinen Gegenstand. Zu dokumentieren bleiben die Gründe der Direktvergabe (procedure_rationale, M820-10) – § 8.8 (S. 37): „Die Gründe für eine Direktvergabe sind in jedem Fall zu dokumentieren, entweder im Vergabevermerk oder an anderer Stelle.“
[EN] Confirms no pure or hidden price competition was used for the planning service. §8.7 (p. 34): quality is "part of the Leistungswettbewerb, which §76 Abs. 1 VgV mandates for planning services." Hidden for a direct award (procurement_procedure = direktvergabe, M820-10): § 8.8 (p. 36): "a direct award is an award in which negotiations are conducted with only one company." Without competition between applicants or bidders this entry has no subject. The reasons for the direct award remain to be documented (procedure_rationale, M820-10) – § 8.8 (p. 37): "the reasons for a direct award are to be documented in every case, either in the award memo or elsewhere."$m$
  FROM worksheet_templates w, standards s
 WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-11' AND f.symbol = 'leistungswettbewerb_only' AND f.active
   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type)) = '7eb40a57f59b9dfebe8e1ac5f92e62fc';
