   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type)) = '270c0a78c3a286a703db7bce44b0163f'
   AND NOT EXISTS (SELECT 1 FROM fields_archive_m820_wa a WHERE a.id = f.id);
UPDATE fields f
   SET visible_when = $m$procurement_procedure != 'direktvergabe'$m$,
       description = $m$Kennzeichen „großes, langlaufendes Projekt“ nach Anh. E.1.4.1; ab dieser Einstufung gilt die Empfehlung („sollte“), das Verhältnis Jahresumsatz zu Jahresauftragswert auf 1,5 zu begrenzen (die 2,0 nach §45 Abs. 2 VgV beziehen sich auf den geschätzten Auftragswert). Das Merkblatt nennt keine Zahlengrenze für „groß/langlaufend“ — Einschätzung liegt beim Ingenieur. Bei Direktvergabe ausgeblendet (procurement_procedure = direktvergabe, M820-10): § 8.8 (S. 36): „Eine Direktvergabe ist eine Vergabe, bei der Verhandlungen mit nur einem Unternehmen geführt werden.“ Ohne Wettbewerb zwischen Bewerbern oder Bietern hat diese Angabe keinen Gegenstand. Zu dokumentieren bleiben die Gründe der Direktvergabe (procedure_rationale, M820-10) – § 8.8 (S. 37): „Die Gründe für eine Direktvergabe sind in jedem Fall zu dokumentieren, entweder im Vergabevermerk oder an anderer Stelle.“
[EN] Flag for a "large, long-running project" per Anh. E.1.4.1; once set, the recommendation ("should") then caps annual revenue to annual contract value at 1.5 (the 2.0 under §45 Abs. 2 VgV refers to the estimated contract value). The Merkblatt gives no numeric definition of "large/long-running" — the call is the engineer's. Hidden for a direct award (procurement_procedure = direktvergabe, M820-10): § 8.8 (p. 36): "a direct award is an award in which negotiations are conducted with only one company." Without competition between applicants or bidders this entry has no subject. The reasons for the direct award remain to be documented (procedure_rationale, M820-10) – § 8.8 (p. 37): "the reasons for a direct award are to be documented in every case, either in the award memo or elsewhere."$m$
