INSERT INTO compliance_requirements_archive_m820_wa SELECT cr.* FROM compliance_requirements cr, worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-13' AND cr.code = 'REQ-12'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = 'bf4ab9222aa1b79fded26b42f8c97dc0'
   AND NOT EXISTS (SELECT 1 FROM compliance_requirements_archive_m820_wa a WHERE a.id = cr.id);
UPDATE compliance_requirements cr
   SET condition = $m$IF procurement_procedure != 'direktvergabe' THEN (min_annual_revenue_multiplier <= 2.0)$m$,
       description = $m$Zum Bestehen darf min_annual_revenue_multiplier höchstens 2,0 betragen. Anh. E.1.4.1 (S. 61): nach § 45 Abs. 2 VgV „nicht mehr als das Zweifache des geschätzten Auftragswerts“; § 8.7 (S. 34): „Dieser darf in der Regel das Zweifache des geschätzten Auftragswerts … betragen.“ Bei großen, langlaufenden Projekten sollte das Verhältnis Jahresumsatz zu Jahresauftragswert 1,5 nicht überschreiten. Gilt nicht bei Direktvergabe (procurement_procedure = direktvergabe, M820-10): § 8.8 (S. 36): „Eine Direktvergabe ist eine Vergabe, bei der Verhandlungen mit nur einem Unternehmen geführt werden.“ – ohne Wettbewerb hat die Prüfung keinen Gegenstand, die Angaben dieses Blatts sind ausgeblendet. Bei VgV-F-Verfahren, Suchverfahren und Planungswettbewerb prüft sie wie bisher; solange procurement_procedure offen ist, wartet sie und nennt die Frage.
[EN] To pass, min_annual_revenue_multiplier must be at most 2.0. Anh. E.1.4.1 (p. 61): under § 45 Abs. 2 VgV "not more than twice the estimated contract value"; § 8.7 (p. 34): "as a rule, it may amount to twice the estimated contract value …". For large, long-running projects the ratio of annual revenue to annual contract value should not exceed 1.5. Does not apply to a direct award (procurement_procedure = direktvergabe, M820-10): § 8.8 (p. 36): "a direct award is an award in which negotiations are conducted with only one company." – without competition the check has no subject, the entries of this sheet are hidden. For VgV-F procedures, search procedures and design competitions it checks as before; while procurement_procedure is open, it waits and names the question.$m$
  FROM worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-13' AND cr.code = 'REQ-12'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = 'bf4ab9222aa1b79fded26b42f8c97dc0';
