   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = 'cf202c8275e36bb9575a4c5db04f86d6'
   AND NOT EXISTS (SELECT 1 FROM compliance_requirements_archive_m820_wa a WHERE a.id = cr.id);
UPDATE compliance_requirements cr
   SET condition = $m$IF procurement_procedure != 'direktvergabe' THEN (price_weight_percent <= 20 OR festpreis_used == true)$m$,
       description = $m$Warnt (sperrt die Freigabe nicht), wenn die Preisgewichtung über 20 % liegt und kein Festpreis verwendet wird (dann 0 %). Anh. E.2.8 (S. 64) druckt eine Erfahrung, keine Pflicht: „Bewährt hat sich ein Bewertungsgewicht für den Preis in Höhe von max. 20 %.“ Eine höhere Preisgewichtung im Vergabevermerk begründen. Gilt nicht bei Direktvergabe (procurement_procedure = direktvergabe, M820-10): § 8.8 (S. 36): „Eine Direktvergabe ist eine Vergabe, bei der Verhandlungen mit nur einem Unternehmen geführt werden.“ – ohne Wettbewerb hat die Prüfung keinen Gegenstand, die Angaben dieses Blatts sind ausgeblendet. Bei VgV-F-Verfahren, Suchverfahren und Planungswettbewerb prüft sie wie bisher; solange procurement_procedure offen ist, wartet sie und nennt die Frage.
[EN] Warns (does not block approval) when the price weighting exceeds 20 % and no fixed price is used (then 0 %). Anh. E.2.8 (p. 64) prints experience, not a duty: "a price weighting of max. 20 % has proven effective." Justify a higher price weighting in the award memo. Does not apply to a direct award (procurement_procedure = direktvergabe, M820-10): § 8.8 (p. 36): "a direct award is an award in which negotiations are conducted with only one company." – without competition the check has no subject, the entries of this sheet are hidden. For VgV-F procedures, search procedures and design competitions it checks as before; while procurement_procedure is open, it waits and names the question.$m$
  FROM worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-14' AND cr.code = 'REQ-15'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = 'cf202c8275e36bb9575a4c5db04f86d6';
