INSERT INTO compliance_requirements_archive_m820_wa SELECT cr.* FROM compliance_requirements cr, worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-14' AND cr.code = 'REQ-16'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = '9b5e5dbc120aad8a88ce37d2d3643139'
   AND NOT EXISTS (SELECT 1 FROM compliance_requirements_archive_m820_wa a WHERE a.id = cr.id);
UPDATE compliance_requirements cr
   SET condition = $m$IF procurement_procedure != 'direktvergabe' THEN (doppelbewertungsverbot_check == true)$m$,
       description = $m$Zum Bestehen darf kein Kriterium sowohl Eignungs- als auch Zuschlagskriterium sein. § 8.10.2.4 (S. 39): „… das Doppelbewertungsverbot, das heißt, verwendete Eignungskriterien dürfen nicht als Zuschlagskriterium verwendet werden.“ Gilt nicht bei Direktvergabe (procurement_procedure = direktvergabe, M820-10): § 8.8 (S. 36): „Eine Direktvergabe ist eine Vergabe, bei der Verhandlungen mit nur einem Unternehmen geführt werden.“ – ohne Wettbewerb hat die Prüfung keinen Gegenstand, die Angaben dieses Blatts sind ausgeblendet. Bei VgV-F-Verfahren, Suchverfahren und Planungswettbewerb prüft sie wie bisher; solange procurement_procedure offen ist, wartet sie und nennt die Frage.
[EN] To pass, no criterion may serve as both an eligibility and an award criterion. § 8.10.2.4 (p. 39): "… the double-evaluation prohibition, meaning eligibility criteria used must not be used as an award criterion." Does not apply to a direct award (procurement_procedure = direktvergabe, M820-10): § 8.8 (p. 36): "a direct award is an award in which negotiations are conducted with only one company." – without competition the check has no subject, the entries of this sheet are hidden. For VgV-F procedures, search procedures and design competitions it checks as before; while procurement_procedure is open, it waits and names the question.$m$
  FROM worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-14' AND cr.code = 'REQ-16'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = '9b5e5dbc120aad8a88ce37d2d3643139';

