-- DWA-M-820-1 M820-04 alternatives_considered: visible_when, description
INSERT INTO fields_archive_m820_wa SELECT f.* FROM fields f, worksheet_templates w, standards s
 WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-04' AND f.symbol = 'alternatives_considered' AND f.active
   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type)) = '5adf8678ad5c880f10832a00b393e90e'
   AND NOT EXISTS (SELECT 1 FROM fields_archive_m820_wa a WHERE a.id = f.id);
UPDATE fields f
   SET visible_when = $m$project_type != 'projekt'$m$,
       description = $m$Register geprüfter Alternativen für das Gesamtsystem-Konzept (§6.3): je Zeile Alternative, Beschreibung, Bewertung. §4.1 verlangt, Alternativen nach grundsätzlich verschiedenen Anforderungen zu erarbeiten und z. B. per Nutzwertanalyse zu bewerten. Bei Projekttyp „Projekt“ ausgeblendet (project_type = projekt, M820-01): die Bedarfsplanung Konzept gehört zur Aufstellung eines Konzepts für das Gesamtsystem – § 4.1 (S. 16): „Vor Aufstellung des Konzepts muss eine „Bedarfsplanung Konzept“ des Auftraggebers aufgestellt werden.“ Für ein Projekt gilt die Bedarfsplanung Projekt auf M820-05 – § 6.4 (S. 28): „Analog zur Bedarfsplanung für das Konzept sind für die aus dem Konzept entstehenden Projekte Bedarfsplanungen gemäß 6.1 zu erstellen.“
[EN] Register of alternatives examined for the system-wide concept (§6.3): one row per alternative with description and evaluation. §4.1 requires working out alternatives with fundamentally different requirements and scoring them, e.g. via a value-benefit analysis. Hidden for project type "Projekt" (project_type = projekt, M820-01): the concept needs assessment belongs to drawing up a concept for the overall system – § 4.1 (p. 16): "before the concept is drawn up, a client 'needs assessment concept' must be drawn up." For a project the project needs assessment on M820-05 applies – § 6.4 (p. 28): "analogous to the needs assessment for the concept, needs assessments according to 6.1 are to be drawn up for the projects arising from the concept."$m$
  FROM worksheet_templates w, standards s
 WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-04' AND f.symbol = 'alternatives_considered' AND f.active
   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type)) = '5adf8678ad5c880f10832a00b393e90e';
