UPDATE fields f
   SET visible_when = $m$project_type != 'projekt'$m$,
       description = $m$Zieltermin für den Abschluss der Bedarfsplanung; Teil des übergeordneten Rahmenterminplans nach §4.3. Bei Projekttyp „Projekt“ ausgeblendet (project_type = projekt, M820-01): die Bedarfsplanung Konzept gehört zur Aufstellung eines Konzepts für das Gesamtsystem – § 4.1 (S. 16): „Vor Aufstellung des Konzepts muss eine „Bedarfsplanung Konzept“ des Auftraggebers aufgestellt werden.“ Für ein Projekt gilt die Bedarfsplanung Projekt auf M820-05 – § 6.4 (S. 28): „Analog zur Bedarfsplanung für das Konzept sind für die aus dem Konzept entstehenden Projekte Bedarfsplanungen gemäß 6.1 zu erstellen.“
[EN] Target date for completing the needs assessment; part of the master schedule under §4.3. Hidden for project type "Projekt" (project_type = projekt, M820-01): the concept needs assessment belongs to drawing up a concept for the overall system – § 4.1 (p. 16): "before the concept is drawn up, a client 'needs assessment concept' must be drawn up." For a project the project needs assessment on M820-05 applies – § 6.4 (p. 28): "analogous to the needs assessment for the concept, needs assessments according to 6.1 are to be drawn up for the projects arising from the concept."$m$
  FROM worksheet_templates w, standards s
 WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-04' AND f.symbol = 'date_bedarfsplanung_complete' AND f.active
   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type)) = 'd1a787a12f913b07110e390c8965daa7';
