   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type)) = 'ce783d4360e2a0d2dd14ef8ec51fa8bb'
   AND NOT EXISTS (SELECT 1 FROM fields_archive_m820_wa a WHERE a.id = f.id);
UPDATE fields f
   SET description = $m$Unterscheidung Konzept (systemweite Planung, z. B. Generalentwässerungsplan) vs. Projekt (konkrete Maßnahme), wie in Bild 1 (§4.1) dargestellt; steuert, ob Bedarfsplanung Konzept oder Bedarfsplanung Projekt zu durchlaufen ist. „Projekt“ blendet auf M820-04 die Bedarfsplanung Konzept aus (Alternativen, Qualitätsziele Konzept, Abschluss und Datum); REQ-02 gilt dann nicht – § 4.1 (S. 16): „Vor Aufstellung des Konzepts muss eine „Bedarfsplanung Konzept“ des Auftraggebers aufgestellt werden.“ Die Aufgabenbeschreibung auf M820-04 (aufgabenbeschreibung_eindeutig) bleibt – § 8.2 (S. 32): „Der Auftraggeber hat bei allen Vergabeverfahren eine Aufgabenbeschreibung zu erstellen.“
[EN] Distinguishes Konzept (system-wide planning, e.g. a drainage master plan) from Projekt (a concrete measure) as shown in Bild 1 (§4.1); determines whether the concept-level or the project-level needs assessment applies. "Projekt" hides the concept needs assessment on M820-04 (alternatives, concept quality targets, completion and date); REQ-02 then does not apply – § 4.1 (p. 16): "before the concept is drawn up, a client 'needs assessment concept' must be drawn up." The task description on M820-04 (aufgabenbeschreibung_eindeutig) remains – § 8.2 (p. 32): "the client must draw up a task description in all award procedures."$m$
  FROM worksheet_templates w, standards s
 WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND f.symbol = 'project_type' AND f.active
   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type)) = 'ce783d4360e2a0d2dd14ef8ec51fa8bb';
-- DWA-M-820-2 820-2-08 cost_planning_din276: label_de, label_en, description
INSERT INTO fields_archive_m820_wa SELECT f.* FROM fields f, worksheet_templates w, standards s
 WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-08' AND f.symbol = 'cost_planning_din276' AND f.active
   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type)) = 'ea06a47e5a95e06b720f9a779fabe30f'
   AND NOT EXISTS (SELECT 1 FROM fields_archive_m820_wa a WHERE a.id = f.id);
UPDATE fields f
   SET label_de = $m$Kostenziele mit einheitlicher Kostenstruktur festgelegt (z. B. DIN 276)$m$,
       label_en = $m$Cost targets set with a uniform cost structure (e.g. DIN 276)$m$,
       description = $m$Bestätigt, dass die Kostenziele des Projekts mit einer im Projekt vereinbarten, einheitlichen und durchgängigen Kostenstruktur festgelegt und dokumentiert sind. DIN 276 ist ein gedrucktes Beispiel, keine Pflicht – § 4.5.1 (S. 29): „Eine einheitliche und durchgängige Kostenstruktur ist im Projekt vereinbart (bspw. DIN 276).“ Eine vereinbarte eigene Kostenaufstellung mit durchgängiger Gliederung genügt. § 4.5.2 (S. 30): „Die Kostenziele müssen als Grundlage für die Finanzierung und Beantragung von Fördermitteln realistisch geplant sein.“ Das Symbol cost_planning_din276 bleibt aus technischen Gründen; gefragt ist die Kostenstruktur, nicht DIN 276. Sperrt über REQ-12.
[EN] Confirms the project's cost targets are set and documented with a uniform, consistent cost structure agreed in the project. DIN 276 is a printed example, not a duty – § 4.5.1 (p. 29): "a uniform and consistent cost structure is agreed in the project (e.g. DIN 276)." An agreed own cost breakdown with a consistent structure suffices. § 4.5.2 (p. 30): "the cost targets must be realistically planned as the basis for financing and for applying for funding." The symbol cost_planning_din276 stays for technical reasons; what is asked is the cost structure, not DIN 276. Blocks via REQ-12.$m$
  FROM worksheet_templates w, standards s
 WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-08' AND f.symbol = 'cost_planning_din276' AND f.active
   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type)) = 'ea06a47e5a95e06b720f9a779fabe30f';
