   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type)) = '36b880f63750c0b7a9cdffce7dd9ebac'
   AND NOT EXISTS (SELECT 1 FROM fields_archive_m820_wa a WHERE a.id = f.id);
UPDATE fields f
   SET visible_when = $m$oeffentlichkeitsbeteiligung_vorgesehen == true$m$,
       description = $m$Bestätigt, dass eine projektspezifische PR-Strategie vorliegt. §5.3.10 (Ziel): "Je nach Projekt ist die Beteiligung der Öffentlichkeit frühzeitig erfolgt", mit Möglichkeiten zur aktiven Mitwirkung der Bürgerschaft. Nur abgefragt, wenn für das Projekt eine Beteiligung der Öffentlichkeit vorgesehen ist (oeffentlichkeitsbeteiligung_vorgesehen = ja, dieses Blatt) – § 5.3.10 (S. 44): „Je nach Projekt ist die Beteiligung der Öffentlichkeit frühzeitig erfolgt.“
[EN] Confirms a project-specific public-relations strategy exists. §5.3.10 (target state): "depending on the project, public participation has taken place early", with options for citizens to actively contribute. Asked only when public participation is intended for the project (oeffentlichkeitsbeteiligung_vorgesehen = yes, this sheet) – § 5.3.10 (p. 44): "depending on the project, the public has been involved early."$m$
  FROM worksheet_templates w, standards s
 WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-14' AND f.symbol = 'public_relations_strategy' AND f.active
   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type)) = '36b880f63750c0b7a9cdffce7dd9ebac';
-- DWA-M-820-1 M820-04 REQ-02 (block, unchanged): condition, description
INSERT INTO compliance_requirements_archive_m820_wa SELECT cr.* FROM compliance_requirements cr, worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-04' AND cr.code = 'REQ-02'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = '25b02c39e0dc7acddb4e88219b199c59'
   AND NOT EXISTS (SELECT 1 FROM compliance_requirements_archive_m820_wa a WHERE a.id = cr.id);
UPDATE compliance_requirements cr
   SET condition = $m$IF project_type != 'projekt' THEN (bedarfsplanung_konzept_complete == true)$m$,
       description = $m$Sperrt die Freigabe, bis bedarfsplanung_konzept_complete (dieses Blatt) bestätigt ist – nur wenn ein Konzept aufgestellt wird (M820-01: project_type = konzept). § 4.1 (S. 16): „Vor Aufstellung des Konzepts muss eine „Bedarfsplanung Konzept“ des Auftraggebers aufgestellt werden.“ § 6.2 (S. 27): „Die Bedarfsplanung für Konzepte als Planung mit einem übergreifenden Charakter ist auf Basis der Hinweise in 6.1 in Abhängigkeit von der Größenordnung und der Komplexität des Konzepts zu erarbeiten.“ Bei Projekttyp „Projekt“ gilt sie nicht: für Projekte gilt die Bedarfsplanung Projekt (M820-05, REQ-03) – § 6.4 (S. 28): „Analog zur Bedarfsplanung für das Konzept sind für die aus dem Konzept entstehenden Projekte Bedarfsplanungen gemäß 6.1 zu erstellen.“ Solange project_type offen ist, wartet sie und nennt die Frage.
[EN] Blocks approval until bedarfsplanung_konzept_complete (this sheet) is confirmed – only when a concept is drawn up (M820-01: project_type = konzept). § 4.1 (p. 16): "before the concept is drawn up, a client 'needs assessment concept' must be drawn up." § 6.2 (p. 27): "the needs assessment for concepts, as planning of an overarching character, is to be worked out on the basis of the notes in 6.1 depending on the size and complexity of the concept." For project type "Projekt" it does not apply: projects need the project needs assessment (M820-05, REQ-03) – § 6.4 (p. 28): "analogous to the needs assessment for the concept, needs assessments according to 6.1 are to be drawn up for the projects arising from the concept." While project_type is open, it waits and names the question.$m$
  FROM worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-04' AND cr.code = 'REQ-02'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = '25b02c39e0dc7acddb4e88219b199c59';
-- DWA-M-820-2 820-2-08 REQ-12 (block, unchanged): condition, description, clause_reference
INSERT INTO compliance_requirements_archive_m820_wa SELECT cr.* FROM compliance_requirements cr, worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-08' AND cr.code = 'REQ-12'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = 'ed6b5541379f72930e0c45f278f61815'
   AND NOT EXISTS (SELECT 1 FROM compliance_requirements_archive_m820_wa a WHERE a.id = cr.id);
UPDATE compliance_requirements cr
   SET condition = $m$cost_planning_din276 == true$m$,
       description = $m$Sperrt die Freigabe, bis cost_planning_din276 (dieses Blatt) bestätigt ist: die Kostenziele sind mit einer im Projekt vereinbarten, einheitlichen Kostenstruktur festgelegt. DIN 276 ist nur ein Beispiel – § 4.5.1 (S. 29): „Eine einheitliche und durchgängige Kostenstruktur ist im Projekt vereinbart (bspw. DIN 276).“ Gesperrt wird wegen § 4.5.2 (S. 30): „Die Kostenziele müssen als Grundlage für die Finanzierung und Beantragung von Fördermitteln realistisch geplant sein.“ – „müssen“ → Sperre.
[EN] Blocks approval until cost_planning_din276 (this sheet) is confirmed: the cost targets are set with a uniform cost structure agreed in the project. DIN 276 is only an example – § 4.5.1 (p. 29): "a uniform and consistent cost structure is agreed in the project (e.g. DIN 276)." It blocks because of § 4.5.2 (p. 30): "the cost targets must be realistically planned as the basis for financing and for applying for funding." – "must" → block.$m$,
       clause_reference = $m$§4.5.1, §4.5.2$m$
  FROM worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-08' AND cr.code = 'REQ-12'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = 'ed6b5541379f72930e0c45f278f61815';
-- DWA-M-820-2 820-2-14 REQ-33 (warn, unchanged): condition, description
INSERT INTO compliance_requirements_archive_m820_wa SELECT cr.* FROM compliance_requirements cr, worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-14' AND cr.code = 'REQ-33'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = '2b8cf207e2905528278abab99d5c6b2a'
   AND NOT EXISTS (SELECT 1 FROM compliance_requirements_archive_m820_wa a WHERE a.id = cr.id);
UPDATE compliance_requirements cr
   SET condition = $m$IF oeffentlichkeitsbeteiligung_vorgesehen == true THEN (public_relations_strategy == true)$m$,
       description = $m$Warnt (sperrt die Freigabe nicht), solange public_relations_strategy (dieses Blatt) nicht bestätigt ist – nur wenn für das Projekt eine Beteiligung der Öffentlichkeit vorgesehen ist (oeffentlichkeitsbeteiligung_vorgesehen = ja, dieses Blatt). § 5.3.10 (S. 44): „Je nach Projekt ist die Beteiligung der Öffentlichkeit frühzeitig erfolgt.“ – Zielbild, „je nach Projekt“ → Warnung und Ja/Nein-Frage. Das „erforderlich“ in § 5.6.5 (Phase „Ausführung“, S. 54) – „ist es erforderlich, ein Konzept für eine Öffentlichkeitsbeteiligung zu erarbeiten“ – gehört zur Ausführungsphase, nicht zu diesem Planungsblatt. Solange die Frage offen ist, wartet die Warnung.
[EN] Warns (does not block approval) while public_relations_strategy (this sheet) is not confirmed – only when public participation is intended for the project (oeffentlichkeitsbeteiligung_vorgesehen = yes, this sheet). § 5.3.10 (p. 44): "depending on the project, the public has been involved early." – a target state, "depending on the project" → warning and a yes/no question. The "erforderlich" in § 5.6.5 (phase "execution", p. 54) – "it is required to develop a concept for public participation" – belongs to the execution phase, not to this planning sheet. While the question is open, the warning waits.$m$
  FROM worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-14' AND cr.code = 'REQ-33'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = '2b8cf207e2905528278abab99d5c6b2a';
-- NEW DWA-M-820-2 820-2-14 oeffentlichkeitsbeteiligung_vorgesehen (boolean, required, section B)
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, widget, ui_config, visible_when, consumer_worksheets, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'oeffentlichkeitsbeteiligung_vorgesehen', $m$Beteiligung der Öffentlichkeit für dieses Projekt vorgesehen (je nach Projekt)$m$, $m$Public participation intended for this project (depending on the project)$m$, 'boolean', NULL, true, $m$§5.3.10$m$,
       $m$Ja/Nein: Ist für dieses Projekt eine Beteiligung der Öffentlichkeit vorgesehen? § 5.3.10 (S. 44) druckt das Ziel projektabhängig: „Je nach Projekt ist die Beteiligung der Öffentlichkeit frühzeitig erfolgt.“ Ja: die PR-Strategie (public_relations_strategy, dieses Blatt) wird abgefragt und REQ-33 warnt, solange sie nicht bestätigt ist. Nein: beides entfällt; den Grund in den Notizen festhalten (z. B. keine Betroffenen außerhalb des Grundstücks). Unbeantwortet bleibt die PR-Frage sichtbar und REQ-33 wartet auf diese Antwort.
[EN] Yes/No: is public participation intended for this project? § 5.3.10 (p. 44) prints the goal as project-dependent: "depending on the project, the public has been involved early." Yes: the PR strategy (public_relations_strategy, this sheet) is asked and REQ-33 warns while it is not confirmed. No: both drop out; record the reason in the notes (e.g. nobody affected outside the property). Unanswered, the PR question stays visible and REQ-33 waits for this answer.$m$,
       'imported_unverified', NULL, NULL, NULL, NULL, 0, true
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id
 WHERE s.code = 'DWA-M-820-2' AND w.code = '820-2-14'
   AND NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'oeffentlichkeitsbeteiligung_vorgesehen');

