UPDATE compliance_requirements cr
   SET condition = $m$IF verantwortung_lph8 != 'entfaellt' THEN (IF phase_ausfuehrung_erreicht == true THEN (quality_supervision_active == true))$m$,
       description = $m$Sperrt die Freigabe, bis quality_supervision_active (dieses Blatt) bestätigt ist – solange LPH 8 stattfindet (820-2-01: verantwortung_lph8 ≠ entfällt), auch bei Eigenleistung des Auftraggebers, und sobald die Phase „Ausführung“ erreicht ist (phase_ausfuehrung_erreicht = ja, dieses Blatt). § 5.6.2 (S. 51): „Die Bauüberwachung muss die geschlossenen Verträge, inklusive der Leistungsverzeichnisse, kennen und sicherstellen, dass die in den Vergabeunterlagen bzw. den Bauverträgen formulierten Qualitätsanforderungen auch tatsächlich um- und durchgesetzt werden.“ Die Pflicht gehört zur Phase „Ausführung“ (§ 5.6, S. 50); vorher (phase_ausfuehrung_erreicht = nein) gilt sie noch nicht. Solange die Phasenfrage offen ist, wartet sie und nennt die Frage.
[EN] Blocks approval until quality_supervision_active (this sheet) is confirmed – while LPH 8 takes place (820-2-01: verantwortung_lph8 ≠ does not occur), also when the client supervises himself, and once the phase "execution" is reached (phase_ausfuehrung_erreicht = yes, this sheet). § 5.6.2 (p. 51): "site supervision must know the concluded contracts, including the bills of quantities, and ensure that the quality requirements formulated in the tender documents or construction contracts are actually implemented and enforced." The duty belongs to the phase "execution" (§ 5.6, p. 50); before it (phase_ausfuehrung_erreicht = no) it does not apply yet. While the phase question is open, it waits and names the question.$m$
  FROM worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-20' AND cr.code = 'REQ-43'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = '712c58e9752dd179d9231851373be46b';
-- DWA-M-820-2 820-2-22 REQ-47 (warn, unchanged): condition, description
INSERT INTO compliance_requirements_archive_m820_wa SELECT cr.* FROM compliance_requirements cr, worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-22' AND cr.code = 'REQ-47'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = 'b30bdde45f5da70385c477708cd34052'
   AND NOT EXISTS (SELECT 1 FROM compliance_requirements_archive_m820_wa a WHERE a.id = cr.id);
UPDATE compliance_requirements cr
   SET condition = $m$IF phase_inbetriebnahme_erreicht == true THEN (abnahme_per_bild4 == true)$m$,
       description = $m$Warnt (sperrt die Freigabe nicht), solange abnahme_per_bild4 (dieses Blatt) nicht bestätigt ist – sobald die Phase „Inbetriebnahme, Testbetrieb Abnahme“ erreicht ist (phase_inbetriebnahme_erreicht = ja, dieses Blatt). § 5.7.3 (S. 57): „Statt einer reinen Abnahme findet eine Abnahmeprüfung statt, die sich dadurch auszeichnet, dass über die reine Sichtprüfung hinaus relevante Funktionalitäten geprüft werden.“ Gedruckt ist ein Zielbild im Indikativ ohne Modalverb – deshalb Warnung. Die Abnahme gehört zur Phase „Inbetriebnahme, Testbetrieb Abnahme“ (§ 5.7, S. 54); vorher gilt die Prüfung noch nicht.
[EN] Warns (does not block approval) while abnahme_per_bild4 (this sheet) is not confirmed – once the phase "commissioning, test operation, acceptance" is reached (phase_inbetriebnahme_erreicht = yes, this sheet). § 5.7.3 (p. 57): "instead of a plain acceptance an acceptance test takes place, distinguished by checking relevant functionalities beyond a plain visual inspection." What is printed is a target state in the indicative without a modal verb – hence a warning. Acceptance belongs to the phase "commissioning, test operation, acceptance" (§ 5.7, p. 54); before it the check does not apply yet.$m$
  FROM worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-22' AND cr.code = 'REQ-47'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = 'b30bdde45f5da70385c477708cd34052';
-- DWA-M-820-2 820-2-23 REQ-48 (block, unchanged): condition, description
INSERT INTO compliance_requirements_archive_m820_wa SELECT cr.* FROM compliance_requirements cr, worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-23' AND cr.code = 'REQ-48'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = '1b7661ee6283cba300b3e8e0406d5e2d'
   AND NOT EXISTS (SELECT 1 FROM compliance_requirements_archive_m820_wa a WHERE a.id = cr.id);
UPDATE compliance_requirements cr
   SET condition = $m$IF phase_inbetriebnahme_erreicht == true THEN (operating_manuals_complete == true)$m$,
       description = $m$Sperrt die Freigabe, bis operating_manuals_complete (dieses Blatt) bestätigt ist – sobald die Phase „Inbetriebnahme, Testbetrieb Abnahme“ erreicht ist (phase_inbetriebnahme_erreicht = ja, 820-2-22). § 5.7.4 (S. 58): „Die erforderlichen Unterlagen der Betriebsanleitung und der technischen Dokumentation liegen zum Zeitpunkt des Montageendes vollständig vor.“ Der gedruckte Zeitpunkt ist das Montageende; während der Planung (phase_inbetriebnahme_erreicht = nein) gilt die Prüfung noch nicht, die Frage ist ausgeblendet. Solange die Phasenfrage offen ist, wartet sie und nennt die Frage.
[EN] Blocks approval until operating_manuals_complete (this sheet) is confirmed – once the phase "commissioning, test operation, acceptance" is reached (phase_inbetriebnahme_erreicht = yes, 820-2-22). § 5.7.4 (p. 58): "the required operating-manual documents and technical documentation are complete at the time the installation ends." The printed point in time is the end of installation; during planning (phase_inbetriebnahme_erreicht = no) the check does not apply yet and the question is hidden. While the phase question is open, it waits and names the question.$m$
  FROM worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-23' AND cr.code = 'REQ-48'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = '1b7661ee6283cba300b3e8e0406d5e2d';
-- DWA-M-820-2 820-2-23 REQ-49 (block, unchanged): condition, description
INSERT INTO compliance_requirements_archive_m820_wa SELECT cr.* FROM compliance_requirements cr, worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-23' AND cr.code = 'REQ-49'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = '280e50679a52cc66d2c94aeb93e42b76'
   AND NOT EXISTS (SELECT 1 FROM compliance_requirements_archive_m820_wa a WHERE a.id = cr.id);
UPDATE compliance_requirements cr
   SET condition = $m$IF phase_inbetriebnahme_erreicht == true THEN (training_complete == true)$m$,
       description = $m$Sperrt die Freigabe, bis training_complete (dieses Blatt) bestätigt ist – sobald die Phase „Inbetriebnahme, Testbetrieb Abnahme“ erreicht ist (phase_inbetriebnahme_erreicht = ja, 820-2-22). § 5.7.5 (S. 59): „Einweisungen des Betriebspersonals erfolgen in jedem Fall in ausreichender Tiefe, um einen optimalen und sicheren Betrieb neuer Anlagenteile zu ermöglichen.“ § 5.7.5 (S. 60): „Rechtzeitig vor Beginn der Inbetriebnahme muss mit den Einweisungen und Schulungen begonnen werden.“ Während der Planung (phase_inbetriebnahme_erreicht = nein) gilt die Prüfung noch nicht, die Frage ist ausgeblendet. Solange die Phasenfrage offen ist, wartet sie und nennt die Frage.
[EN] Blocks approval until training_complete (this sheet) is confirmed – once the phase "commissioning, test operation, acceptance" is reached (phase_inbetriebnahme_erreicht = yes, 820-2-22). § 5.7.5 (p. 59): "instruction of the operating personnel takes place in every case in sufficient depth to enable optimal and safe operation of new plant components." § 5.7.5 (p. 60): "instruction and training must begin in good time before commissioning starts." During planning (phase_inbetriebnahme_erreicht = no) the check does not apply yet and the question is hidden. While the phase question is open, it waits and names the question.$m$
  FROM worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-23' AND cr.code = 'REQ-49'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = '280e50679a52cc66d2c94aeb93e42b76';
-- DWA-M-820-2 820-2-24 REQ-51 (warn, unchanged): condition, description
INSERT INTO compliance_requirements_archive_m820_wa SELECT cr.* FROM compliance_requirements cr, worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-24' AND cr.code = 'REQ-51'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = '0b4c97b02f219454f2365c0f56a2aec5'
   AND NOT EXISTS (SELECT 1 FROM compliance_requirements_archive_m820_wa a WHERE a.id = cr.id);
UPDATE compliance_requirements cr
   SET condition = $m$IF verantwortung_lph9 != 'entfaellt' THEN (IF bauleistungen_vergeben == true THEN (IF phase_gewaehrleistung_erreicht == true THEN (warranty_count >= 1)))$m$,
       description = $m$Warnt (sperrt die Freigabe nicht), solange LPH 9 stattfindet (820-2-01: verantwortung_lph9 ≠ entfällt), Bauleistungen an ausführende Firmen vergeben werden (820-2-17: bauleistungen_vergeben = ja), die Phase „Gewährleistung“ erreicht ist (phase_gewaehrleistung_erreicht = ja, dieses Blatt) und der Gewährleistungskalender (gewaehrleistungen, dieses Blatt) keine vollständige Zeile hat (warranty_count ≥ 1). § 5.8.2 (S. 61): „Die Abnahmen werden mit Angabe des Beginns und des Endes der jeweiligen Gewährleistungsfrist dokumentiert.“ „Es wird ein Gewährleistungskalender, mit Angabe des Beginns und des Endes der jeweiligen Gewährleistungsfristen, für jeden Auftragnehmer und für jede ausführende Firma geführt.“ Die Frist beginnt mit der Abnahme – § 5.7.1 (S. 54): „Mit der Abnahme geht die Gefahr auf den Auftraggeber über, der Werklohn wird fällig, die Gewährleistungsfrist beginnt.“ Vorher (phase_gewaehrleistung_erreicht = nein) gilt die Prüfung noch nicht, der Gewährleistungsteil ist ausgeblendet. Erbringt der Auftraggeber die Bauleistungen selbst (bauleistungen_vergeben = nein), gilt sie nicht. Gedruckt ist ein Zielbild im Indikativ ohne Modalverb – deshalb Warnung.
[EN] Warns (does not block approval) while LPH 9 takes place (820-2-01: verantwortung_lph9 ≠ does not occur), construction works are awarded to executing firms (820-2-17: bauleistungen_vergeben = yes), the phase "warranty" is reached (phase_gewaehrleistung_erreicht = yes, this sheet) and the warranty calendar (gewaehrleistungen, this sheet) has no complete row (warranty_count ≥ 1). § 5.8.2 (p. 61): "the acceptances are documented with the start and end of the respective warranty period." "A warranty calendar with the start and end of the respective warranty periods is kept for every contractor and every executing firm." The period begins with acceptance – § 5.7.1 (p. 54): "with acceptance the risk passes to the client, the payment for the work falls due, the warranty period begins." Before that (phase_gewaehrleistung_erreicht = no) the check does not apply yet and the warranty part is hidden. If the client performs the construction works itself (bauleistungen_vergeben = no), it does not apply. What is printed is a target state in the indicative without a modal verb – hence a warning.$m$
  FROM worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-24' AND cr.code = 'REQ-51'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = '0b4c97b02f219454f2365c0f56a2aec5';
-- DWA-M-820-2 820-2-24 REQ-52 (block, unchanged): condition, description
INSERT INTO compliance_requirements_archive_m820_wa SELECT cr.* FROM compliance_requirements cr, worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-24' AND cr.code = 'REQ-52'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = 'ae9c338958d85bd38ac0fa05f1a52f03'
   AND NOT EXISTS (SELECT 1 FROM compliance_requirements_archive_m820_wa a WHERE a.id = cr.id);
UPDATE compliance_requirements cr
   SET condition = $m$IF verantwortung_lph9 != 'entfaellt' THEN (IF bauleistungen_vergeben == true THEN (IF phase_gewaehrleistung_erreicht == true THEN (defect_tracking_active == true)))$m$,
       description = $m$Sperrt die Freigabe, bis defect_tracking_active (dieses Blatt) bestätigt ist – solange LPH 9 stattfindet (820-2-01: verantwortung_lph9 ≠ entfällt), Bauleistungen an ausführende Firmen vergeben werden (820-2-17: bauleistungen_vergeben = ja) und die Phase „Gewährleistung“ erreicht ist (phase_gewaehrleistung_erreicht = ja, dieses Blatt). § 5.8.3 (S. 62): „Festgestellte Mängel sind zeitnah zum Auftreten bei der ausführenden Firma zu rügen.“ Die Gewährleistungsfrist beginnt mit der Abnahme – § 5.7.1 (S. 54): „Mit der Abnahme geht die Gefahr auf den Auftraggeber über, der Werklohn wird fällig, die Gewährleistungsfrist beginnt.“ Vorher (phase_gewaehrleistung_erreicht = nein) gilt die Prüfung noch nicht. Erbringt der Auftraggeber die Bauleistungen selbst (bauleistungen_vergeben = nein), gibt es keine ausführende Firma, bei der Mängel zu rügen wären: die Prüfung gilt dann nicht. Solange eine dieser Fragen offen ist, wartet sie (sperrt) und nennt die Frage.
[EN] Blocks approval until defect_tracking_active (this sheet) is confirmed – while LPH 9 takes place (820-2-01: verantwortung_lph9 ≠ does not occur), construction works are awarded to executing firms (820-2-17: bauleistungen_vergeben = yes) and the phase "warranty" is reached (phase_gewaehrleistung_erreicht = yes, this sheet). § 5.8.3 (p. 62): "defects found are to be notified to the executing firm promptly after they occur." The warranty period begins with acceptance – § 5.7.1 (p. 54): "with acceptance the risk passes to the client, the payment for the work falls due, the warranty period begins." Before that (phase_gewaehrleistung_erreicht = no) the check does not apply yet. If the client performs the construction works itself (bauleistungen_vergeben = no), there is no executing firm to notify defects to: the check then does not apply. While one of these questions is open, it waits (blocks) and names the question.$m$
  FROM worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-24' AND cr.code = 'REQ-52'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = 'ae9c338958d85bd38ac0fa05f1a52f03';
-- NEW DWA-M-820-2 820-2-20 phase_ausfuehrung_erreicht (boolean, required, section B)
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, widget, ui_config, visible_when, consumer_worksheets, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'phase_ausfuehrung_erreicht', $m$Phase „Ausführung“ erreicht (Bauausführung hat begonnen)$m$, $m$Phase "execution" reached (construction has started)$m$, 'boolean', NULL, true, $m$§5.6$m$,
       $m$Ja/Nein: Hat die Bauausführung begonnen? Die Qualitätsüberwachung (quality_supervision_active, dieses Blatt; § 5.6.2) und die durchgeführte Öffentlichkeitsarbeit (oeffentlichkeitsarbeit_durchgefuehrt, 820-2-21; § 5.6.5) gehören zur Phase „Ausführung“ (§ 5.6, S. 50). § 5.6.1 (S. 51): „In der Phase der Realisierung eines Projekts (Bauphase) muss sich die Aufmerksamkeit in der Projektführung insbesondere auf die Einhaltung des Termin- und Kostenrahmens, wie auch der Qualitäten richten.“ Nein = Phase noch nicht erreicht: beide Fragen sind ausgeblendet, REQ-43 gilt noch nicht. Ja: alles wie bisher. Mit Baubeginn auf Ja umstellen. Unbeantwortet bleiben die Fragen sichtbar und REQ-43 wartet (sperrt) und nennt diese Frage. Werkzeug-Frage nach dem Vorbild von DWA-M 820-3 („Phase noch nicht erreicht“); die Controlling-Frequenz und die Kompetenzen der Bauüberwachung bleiben – § 5.6.3 (S. 53): „Diese Regelungen sind schon in der Phase der Beauftragung des Auftragnehmers zu erarbeiten und festzulegen.“
[EN] Yes/No: has construction started? Quality supervision (quality_supervision_active, this sheet; § 5.6.2) and public relations performed (oeffentlichkeitsarbeit_durchgefuehrt, 820-2-21; § 5.6.5) belong to the phase "execution" (§ 5.6, p. 50). § 5.6.1 (p. 51): "in the realisation phase of a project (construction phase), project management must focus in particular on keeping to the schedule and cost frame as well as the qualities." No = phase not reached yet: both questions are hidden, REQ-43 does not apply yet. Yes: everything as before. Switch to Yes when construction starts. Unanswered, the questions stay visible and REQ-43 waits (blocks) and names this question. Tool question modelled on DWA-M 820-3 ("phase not reached yet"); the controlling cadence and the site-supervision competences remain – § 5.6.3 (p. 53): "these arrangements are to be worked out and fixed already in the phase of commissioning the contractor."$m$,
       'imported_unverified', NULL, NULL, NULL, ARRAY['820-2-21']::text[], 0, true
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id
 WHERE s.code = 'DWA-M-820-2' AND w.code = '820-2-20'
   AND NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'phase_ausfuehrung_erreicht');
-- NEW DWA-M-820-2 820-2-22 phase_inbetriebnahme_erreicht (boolean, required, section B)
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, widget, ui_config, visible_when, consumer_worksheets, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'phase_inbetriebnahme_erreicht', $m$Phase „Inbetriebnahme, Testbetrieb Abnahme“ erreicht (Montageende steht an)$m$, $m$Phase "commissioning, test operation, acceptance" reached (end of installation imminent)$m$, 'boolean', NULL, true, $m$§5.7$m$,
       $m$Ja/Nein: Ist die Phase „Inbetriebnahme, Testbetrieb Abnahme“ (§ 5.7, S. 54) erreicht, d. h. steht das Montageende an? Die Abnahmeprüfung (abnahme_per_bild4, dieses Blatt; § 5.7.3), die Betriebsanleitungen (operating_manuals_complete, 820-2-23) und die Einweisung (training_complete, 820-2-23) sind an diese Phase gebunden – § 5.7.4 (S. 58): „Die erforderlichen Unterlagen der Betriebsanleitung und der technischen Dokumentation liegen zum Zeitpunkt des Montageendes vollständig vor.“ § 5.7.5 (S. 60): „Rechtzeitig vor Beginn der Inbetriebnahme muss mit den Einweisungen und Schulungen begonnen werden.“ Nein = Phase noch nicht erreicht: diese drei Fragen sind ausgeblendet, REQ-47, REQ-48 und REQ-49 gelten noch nicht. Ja: alles wie bisher. Die Planungspflichten dieses Blatts bleiben in jeder Phase (Testbetrieb geplant, REQ-46; Schlussdokumentation als Abnahme-Voraussetzung; Inbetriebnahme organisiert, REQ-50) – § 5.7.2 (S. 57): „Die Kosten für die Beauftragung des Testbetriebs müssen bereits zu Beginn des Projekts in den Finanzplan eingestellt … werden.“ Unbeantwortet bleiben die Fragen sichtbar und REQ-48/REQ-49 warten (sperren) und nennen diese Frage. Werkzeug-Frage nach dem Vorbild von DWA-M 820-3 („Phase noch nicht erreicht“).
[EN] Yes/No: is the phase "commissioning, test operation, acceptance" (§ 5.7, p. 54) reached, i.e. is the end of installation imminent? The acceptance test (abnahme_per_bild4, this sheet; § 5.7.3), the operating manuals (operating_manuals_complete, 820-2-23) and the instruction (training_complete, 820-2-23) are tied to this phase – § 5.7.4 (p. 58): "the required operating-manual documents and technical documentation are complete at the time the installation ends." § 5.7.5 (p. 60): "instruction and training must begin in good time before commissioning starts." No = phase not reached yet: these three questions are hidden, REQ-47, REQ-48 and REQ-49 do not apply yet. Yes: everything as before. The planning duties of this sheet remain in every phase (test operation planned, REQ-46; final documentation as a precondition of acceptance; commissioning organised, REQ-50) – § 5.7.2 (p. 57): "the costs of commissioning the test operation must already be included in the financial plan at the start of the project …". Unanswered, the questions stay visible and REQ-48/REQ-49 wait (block) and name this question. Tool question modelled on DWA-M 820-3 ("phase not reached yet").$m$,
       'imported_unverified', NULL, NULL, NULL, ARRAY['820-2-23']::text[], 0, true
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id
 WHERE s.code = 'DWA-M-820-2' AND w.code = '820-2-22'
   AND NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'phase_inbetriebnahme_erreicht');
-- NEW DWA-M-820-2 820-2-24 phase_gewaehrleistung_erreicht (boolean, required, section B)
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, widget, ui_config, visible_when, consumer_worksheets, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'phase_gewaehrleistung_erreicht', $m$Phase „Gewährleistung“ erreicht (Abnahme erfolgt)$m$, $m$Phase "warranty" reached (acceptance done)$m$, 'boolean', NULL, true, $m$§5.8, §5.7.1$m$,
       $m$Ja/Nein: Ist die Phase „Gewährleistung“ (§ 5.8, S. 61) erreicht, d. h. sind Bauleistungen abgenommen? Die Gewährleistungsfrist beginnt mit der Abnahme – § 5.7.1 (S. 54): „Mit der Abnahme geht die Gefahr auf den Auftraggeber über, der Werklohn wird fällig, die Gewährleistungsfrist beginnt.“ Nein = Phase noch nicht erreicht: Gewährleistungsbeginn und -ende, Mängelverfolgung und Gewährleistungskalender sind ausgeblendet, REQ-51 und REQ-52 gelten noch nicht. Ja: alles wie bisher. Wer für LPH 9 verantwortlich ist (verantwortlich_lph9_name, REQ-52-2), bleibt in jeder Phase gefragt. Nur sichtbar, solange LPH 9 stattfindet und Bauleistungen vergeben werden. Unbeantwortet bleiben die Fragen sichtbar und REQ-52 wartet (sperrt) und nennt diese Frage. Werkzeug-Frage nach dem Vorbild von DWA-M 820-3 („Phase noch nicht erreicht“).
[EN] Yes/No: is the phase "warranty" (§ 5.8, p. 61) reached, i.e. have construction works been accepted? The warranty period begins with acceptance – § 5.7.1 (p. 54): "with acceptance the risk passes to the client, the payment for the work falls due, the warranty period begins." No = phase not reached yet: warranty start and end, defect tracking and the warranty calendar are hidden, REQ-51 and REQ-52 do not apply yet. Yes: everything as before. Who is responsible for LPH 9 (verantwortlich_lph9_name, REQ-52-2) stays asked in every phase. Only shown while LPH 9 takes place and construction works are awarded. Unanswered, the questions stay visible and REQ-52 waits (blocks) and names this question. Tool question modelled on DWA-M 820-3 ("phase not reached yet").$m$,
       'imported_unverified', NULL, NULL, $m$(verantwortung_lph9 != 'entfaellt') AND (bauleistungen_vergeben == true)$m$, NULL, 0, true
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id
 WHERE s.code = 'DWA-M-820-2' AND w.code = '820-2-24'
   AND NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'phase_gewaehrleistung_erreicht');

-- ── item 4 · missing options ──
-- DWA-M-820-1 M820-01 sector: enum_values, description
INSERT INTO fields_archive_m820_wa SELECT f.* FROM fields f, worksheet_templates w, standards s
 WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND f.symbol = 'sector' AND f.active
   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type)) = '5bb6401c2c073ffb190637432a21b636'
   AND NOT EXISTS (SELECT 1 FROM fields_archive_m820_wa a WHERE a.id = f.id);
UPDATE fields f
   SET enum_values = $m$[{"value":"wasserwirtschaft","label_de":"Wasserwirtschaft","label_en":"Water management (Wasserwirtschaft)","order_index":1,"regulation_reference":"§1"},{"value":"wastewater","label_de":"Abwasser","label_en":"Wastewater","order_index":2,"regulation_reference":"§1"},{"value":"water_supply","label_de":"Wasserversorgung","label_en":"Water supply","order_index":3,"regulation_reference":"§1"},{"value":"flood_protection","label_de":"Hochwasserschutz","label_en":"Flood protection","order_index":4,"regulation_reference":"§1"},{"value":"waste","label_de":"Abfall","label_en":"Waste","order_index":5,"regulation_reference":"§1"},{"value":"water_engineering","label_de":"Wasserbau","label_en":"Water engineering","order_index":6,"regulation_reference":"§1"},{"value":"other","label_de":"Sonstiges","label_en":"Other","order_index":7,"regulation_reference":"§1"}]$m$::jsonb,
       description = $m$Wassersektor des Projekts. § 1 (S. 10): „Die in diesem Merkblatt formulierten Empfehlungen beziehen sich im Wesentlichen auf Ingenieurleistungen für Projekte im Bereich Wasserwirtschaft, Wasserbau, Abwasser und Abfall.“ Die vier gedruckten Bereiche stehen als Optionen zur Wahl („Wasserwirtschaft“, „Wasserbau“, „Abwasser“, „Abfall“); „Wasserversorgung“ und „Hochwasserschutz“ sind Werkzeug-Unterteilungen. Projekte außerhalb dieser Sektoren liegen außerhalb des Anwendungsbereichs (REQ-01); bei „Sonstiges“ die Zuordnung selbst begründen.
[EN] Water sector of the project. § 1 (p. 10): "the recommendations formulated in this Merkblatt relate essentially to engineering services for projects in the field of Wasserwirtschaft (water management), Wasserbau (hydraulic engineering), Abwasser (wastewater) and Abfall (waste)." The four printed fields are offered as options ("water management", "hydraulic engineering", "wastewater", "waste"); "water supply" and "flood protection" are tool subdivisions. Projects outside these sectors fall outside the scope (REQ-01); for "Other", justify the fit yourself.$m$
  FROM worksheet_templates w, standards s
 WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND f.symbol = 'sector' AND f.active
   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type)) = '5bb6401c2c073ffb190637432a21b636';
-- DWA-M-820-2 820-2-05 mgmt_cycle_frequency: enum_values, description
INSERT INTO fields_archive_m820_wa SELECT f.* FROM fields f, worksheet_templates w, standards s
 WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND f.symbol = 'mgmt_cycle_frequency' AND f.active
   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type)) = '1a47441822a439d434366071c1614115'
   AND NOT EXISTS (SELECT 1 FROM fields_archive_m820_wa a WHERE a.id = f.id);
UPDATE fields f
   SET enum_values = $m$[{"value":"zweiwoechentlich","label_de":"Zweiwöchentlich","label_en":"Every two weeks","order_index":1,"regulation_reference":"§4.2"},{"value":"dreiwoechentlich","label_de":"Dreiwöchentlich","label_en":"Every three weeks","order_index":2,"regulation_reference":"§4.2"},{"value":"vierwoechentlich","label_de":"Vierwöchentlich","label_en":"Every four weeks","order_index":3,"regulation_reference":"§4.2"},{"value":"monatlich","label_de":"Monatlich","label_en":"Monthly","order_index":4,"regulation_reference":"§5.6.1"},{"value":"anlassbezogen","label_de":"Anlassbezogen (Werkzeug-Option)","label_en":"Event-driven (tool option)","order_index":5}]$m$::jsonb,
       description = $m$Takt, in dem der Management-Regelkreis (Planen-Durchführen-Kontrollieren-Steuern) durchlaufen wird. §4.2 nennt zwei- bis vierwöchige Abstände als üblichen Rhythmus. „Monatlich“: ein monatlicher Takt ist in §5.6.1 (S. 51) gedruckt („eine regelmäßige, zum Beispiel monatliche Kontrolle der auf der Baustelle erbrachten Leistungen“); §4.2 (S. 20) nennt für den Regelkreis „meist zwei- bis vierwöchigen Abständen“. „Anlassbezogen (Werkzeug-Option)“ ist nicht gedruckt: für Projekte, in denen der Regelkreis bei Entscheidungen und Änderungen statt in festen Abständen durchlaufen wird. § 4.2 (S. 20): „… die kontinuierlich in meist zwei- bis vierwöchigen Abständen durchlaufen werden“ – „meist“ lässt Ausnahmen zu. Keine Prüfung liest dieses Feld.
[EN] Cadence at which the management cycle (Plan-Do-Check-Steer) is run. §4.2 names a two- to four-week interval as the usual rhythm. "Monthly": a monthly cadence is printed in §5.6.1 (p. 51) ("a regular, for example monthly check of the work performed on site"); §4.2 (p. 20) names "mostly two- to four-week intervals" for the management cycle. "Event-driven (tool option)" is not printed: for projects in which the cycle is run at decisions and changes instead of at fixed intervals. § 4.2 (p. 20): "… which are run through continuously at mostly two- to four-week intervals" – "mostly" admits exceptions. No check reads this field.$m$
  FROM worksheet_templates w, standards s
 WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND f.symbol = 'mgmt_cycle_frequency' AND f.active
   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type)) = '1a47441822a439d434366071c1614115';
-- DWA-M-820-1 M820-01 REQ-01 (warn, unchanged): condition, description
INSERT INTO compliance_requirements_archive_m820_wa SELECT cr.* FROM compliance_requirements cr, worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND cr.code = 'REQ-01'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = '80d3f958e6b43bf99e8ed68e64c5b634'
   AND NOT EXISTS (SELECT 1 FROM compliance_requirements_archive_m820_wa a WHERE a.id = cr.id);
UPDATE compliance_requirements cr
   SET condition = $m$sector IN {wasserwirtschaft,wastewater,water_supply,flood_protection,waste,water_engineering,other}$m$,
       description = $m$Werkzeug-Prüfung (Geltungsbereich, keine gedruckte Pflicht) – warnt nur, sperrt die Freigabe nicht. Prüft, ob ein Sektor gewählt ist. § 1 (S. 10): Die Empfehlungen beziehen sich „im Wesentlichen auf Ingenieurleistungen für Projekte im Bereich Wasserwirtschaft, Wasserbau, Abwasser und Abfall“. Jede Auswahl der Liste (auch „Wasserwirtschaft“ und „Sonstiges“) besteht; bei „Sonstiges“ die Zuordnung zum Anwendungsbereich selbst begründen. Dazu den Sektor auf diesem Blatt eintragen.
[EN] Tool check (scope, not a printed duty) – warns only, never blocks approval. Checks that a sector is chosen. § 1 (p. 10): the recommendations relate "essentially to engineering services for projects in the field of Wasserwirtschaft, Wasserbau, Abwasser and Abfall". Every list option (including "Water management" and "Other") passes; for "Other", justify the scope fit yourself. Enter the sector on this sheet.$m$
  FROM worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND cr.code = 'REQ-01'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = '80d3f958e6b43bf99e8ed68e64c5b634';

