-- DWA-M-820-1 M820-05 bedarfsplanung_projekt_complete: description
INSERT INTO fields_archive_m820_wa SELECT f.* FROM fields f, worksheet_templates w, standards s
 WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-05' AND f.symbol = 'bedarfsplanung_projekt_complete' AND f.active
   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type)) = '7a7d4d089830ea8d43c0819568833e94'
   AND NOT EXISTS (SELECT 1 FROM fields_archive_m820_wa a WHERE a.id = f.id);
UPDATE fields f
   SET description = $m$Bestätigt, dass die projektbezogene Bedarfsplanung (§6.4) abgeschlossen ist; sie bildet die Grundlage für die Bildung der Leistungspakete und den Einstieg in die Vergabe. Einmal beantworten: dieselbe Frage nach der Bedarfsplanung stellen M820-04 / M820-05 (DWA-M 820-1), 820-2-11 framework_conditions_clarified (DWA-M 820-2) und M8203-11 PZ 6.2-1 (DWA-M 820-3). Maßgeblich (Master) ist die Antwort hier auf M820-05 (bei Projekttyp Konzept: bedarfsplanung_konzept_complete auf M820-04); die anderen Blätter wiederholen sie und dürfen ihr nicht widersprechen. Eine automatische Übernahme gibt es noch nicht.
[EN] Confirms the project-level needs assessment (§6.4) is complete; it is the basis for forming the service packages and for entering procurement. Answer once: the same needs-assessment question is asked on M820-04 / M820-05 (DWA-M 820-1), 820-2-11 framework_conditions_clarified (DWA-M 820-2) and M8203-11 PZ 6.2-1 (DWA-M 820-3). The answer here on M820-05 is the master (for project type Konzept: bedarfsplanung_konzept_complete on M820-04); the other sheets repeat it and must not contradict it. There is no automatic carry-over yet.$m$
  FROM worksheet_templates w, standards s
 WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-05' AND f.symbol = 'bedarfsplanung_projekt_complete' AND f.active
   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type)) = '7a7d4d089830ea8d43c0819568833e94';
-- DWA-M-820-1 M820-04 aufgabenbeschreibung_eindeutig: description
