 WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-04' AND f.symbol = 'aufgabenbeschreibung_eindeutig' AND f.active
   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type)) = '455fb6806fb22adaa7600f29e6a30b9f'
   AND NOT EXISTS (SELECT 1 FROM fields_archive_m820_wa a WHERE a.id = f.id);
UPDATE fields f
   SET description = $m$Bestätigt, dass die Aufgabenbeschreibung eindeutig und erschöpfend ist, sodass alle Bewerber sie im gleichen Sinn verstehen — Pflicht nach §121 Abs. 1 GWB und §8.2. Einmal beantworten: diese Antwort wiederholt die Bedarfsplanung aus DWA-M 820-1. Maßgeblich (Master) ist M820-05 bedarfsplanung_projekt_complete (bei Projekttyp Konzept: M820-04 bedarfsplanung_konzept_complete); dieselbe Frage steht auch auf M820-04, 820-2-11 (framework_conditions_clarified) und M8203-11 (PZ 6.2-1). Hier dasselbe eintragen wie dort – die Antworten dürfen sich nicht widersprechen. Eine automatische Übernahme gibt es noch nicht.
[EN] Confirms the task description is unambiguous and exhaustive enough that every applicant understands it the same way — mandatory under §121 Abs. 1 GWB and §8.2. Answer once: this answer repeats the needs assessment of DWA-M 820-1. The master is M820-05 bedarfsplanung_projekt_complete (for project type Konzept: M820-04 bedarfsplanung_konzept_complete); the same question also stands on M820-04, 820-2-11 (framework_conditions_clarified) and M8203-11 (PZ 6.2-1). Enter the same as there – the answers must not contradict each other. There is no automatic carry-over yet.$m$
  FROM worksheet_templates w, standards s
 WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-04' AND f.symbol = 'aufgabenbeschreibung_eindeutig' AND f.active
   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type)) = '455fb6806fb22adaa7600f29e6a30b9f';
