   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type)) = 'f4ba72c3be2f2459fbde6a786af40405'
   AND NOT EXISTS (SELECT 1 FROM fields_archive_m820_wa a WHERE a.id = f.id);
UPDATE fields f
   SET description = $m$Bestätigt, dass technische, rechtliche, organisatorische und finanzielle Randbedingungen geklärt sind. §5.2.2 (Ziel): umfassende Bedarfsplanung nach DWA-M 820-1; Förderfähigkeit ist geklärt, Voraussetzungen sind bekannt. Einmal beantworten: diese Antwort wiederholt die Bedarfsplanung aus DWA-M 820-1. Maßgeblich (Master) ist M820-05 bedarfsplanung_projekt_complete (bei Projekttyp Konzept: M820-04 bedarfsplanung_konzept_complete); dieselbe Frage steht auch auf M820-04, 820-2-11 (framework_conditions_clarified) und M8203-11 (PZ 6.2-1). Hier dasselbe eintragen wie dort – die Antworten dürfen sich nicht widersprechen. Eine automatische Übernahme gibt es noch nicht.
[EN] Confirms technical, legal, organisational and financial preconditions are clarified. §5.2.2 (target state): comprehensive needs planning per DWA-M 820-1; funding eligibility is clarified, preconditions are known. Answer once: this answer repeats the needs assessment of DWA-M 820-1. The master is M820-05 bedarfsplanung_projekt_complete (for project type Konzept: M820-04 bedarfsplanung_konzept_complete); the same question also stands on M820-04, 820-2-11 (framework_conditions_clarified) and M8203-11 (PZ 6.2-1). Enter the same as there – the answers must not contradict each other. There is no automatic carry-over yet.$m$
  FROM worksheet_templates w, standards s
 WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-11' AND f.symbol = 'framework_conditions_clarified' AND f.active
   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type)) = 'f4ba72c3be2f2459fbde6a786af40405';
-- DWA-M-820-3 M8203-11 pz_62_1_status: description
INSERT INTO fields_archive_m820_wa SELECT f.* FROM fields f, worksheet_templates w, standards s
 WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-11' AND f.symbol = 'pz_62_1_status' AND f.active
   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type)) = '8c29edf8101787bdfe513e4234347d6b'
   AND NOT EXISTS (SELECT 1 FROM fields_archive_m820_wa a WHERE a.id = f.id);
UPDATE fields f
   SET description = $m$PZ 6.2-1 (§6.2 Phasenziele, gedr. S. 14): Die „Bedarfsplanung Projekt“ beschreibt die Anforderungen und Rahmenbedingungen so ausführlich und konkret, dass Bauherr und Planende ein gleiches Verständnis der Projektaufgabe entwickeln und klären können, welche Leistungen in Eigenleistung erbracht und welche vergeben werden müssen. Bewerten Sie: Erreicht / Teilweise erreicht (löst die Projektstopp-Prüfung unten aus) / Nicht erreicht (blockiert bei Projekttyp Einzelprojekt oder Beides) / Nicht zutreffend / Phase noch nicht erreicht (nur wählen, wenn die Leistungsphase wirklich noch nicht abgeschlossen ist). Einmal beantworten: diese Antwort wiederholt die Bedarfsplanung aus DWA-M 820-1. Maßgeblich (Master) ist M820-05 bedarfsplanung_projekt_complete (bei Projekttyp Konzept: M820-04 bedarfsplanung_konzept_complete); dieselbe Frage steht auch auf M820-04, 820-2-11 (framework_conditions_clarified) und M8203-11 (PZ 6.2-1). Hier dasselbe eintragen wie dort – die Antworten dürfen sich nicht widersprechen. Eine automatische Übernahme gibt es noch nicht.
[EN] PZ 6.2-1 (§ 6.2 phase goals, printed p. 14): 'Needs planning (project)' describes the requirements and framework conditions in enough detail that client and planner develop a shared understanding of the task and clarify which services are performed in-house and which are awarded. Rate it: Met / Partially met (triggers the Projektstopp review below) / Not met (blocks for project type einzelprojekt or both) / Not applicable / Phase not reached yet (choose only if the service phase genuinely has not closed). Answer once: this answer repeats the needs assessment of DWA-M 820-1. The master is M820-05 bedarfsplanung_projekt_complete (for project type Konzept: M820-04 bedarfsplanung_konzept_complete); the same question also stands on M820-04, 820-2-11 (framework_conditions_clarified) and M8203-11 (PZ 6.2-1). Enter the same as there – the answers must not contradict each other. There is no automatic carry-over yet.$m$
  FROM worksheet_templates w, standards s
 WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-11' AND f.symbol = 'pz_62_1_status' AND f.active
   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type)) = '8c29edf8101787bdfe513e4234347d6b';

-- ── item 6 · other rule sets register (820-2-04) ──
-- NEW DWA-M-820-2 820-2-04 weitere_regelwerke (json, optional, section C)
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, widget, ui_config, visible_when, consumer_worksheets, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'weitere_regelwerke', $m$Weitere Regelwerke (z. B. FLL, VDI, Fachliteratur)$m$, $m$Other rule sets (e.g. FLL, VDI, technical literature)$m$, 'json', NULL, false, $m$§6.2, §6.3.2$m$,
       $m$Register weiterer Regelwerke, die dem Projekt zugrunde liegen und weder DIN- noch DWA-Regelwerke sind (z. B. FLL-Richtlinien, VDI-Richtlinien, Fachliteratur), mit Ausgabe/Stand und Anwendung im Projekt. Muster wie die beiden Register für DIN-Normen und DWA-Regelwerke auf diesem Blatt. § 6.3.2 (S. 65): „Dem Projekt zugrunde liegende Richtlinien und Regelwerke werden zu Projektbeginn auf Aktualität geprüft und aufgelistet.“ § 6.2 (S. 63): „Zu unterscheiden sind grundsätzlich technische Regelwerke und rechtliche Vorgaben, wobei diese beiden Gruppen sich teilweise überschneiden.“ § 6.3.1 (S. 65) nennt als Maßstab „die anerkannten Regeln der Technik“. Das Merkblatt druckt keine Liste der Regelwerksarten; das dritte Register ist eine Werkzeug-Ergänzung. Nicht verpflichtend, keine Prüfung.
[EN] Register of further rule sets the project is based on that are neither DIN nor DWA rules (e.g. FLL guidelines, VDI guidelines, technical literature), with edition/status and application in the project. Same pattern as the two registers for DIN standards and DWA rules on this sheet. § 6.3.2 (p. 65): "guidelines and rule sets underlying the project are checked for currency and listed at project start." § 6.2 (p. 63): "a basic distinction is to be made between technical rule sets and legal requirements, the two groups partly overlapping." § 6.3.1 (p. 65) names "the recognised rules of technology" as the yardstick. The Merkblatt prints no list of rule-set types; the third register is a tool addition. Not required, no check.$m$,
       'imported_unverified', (SELECT f0.widget FROM fields f0 WHERE f0.worksheet_template_id = w.id AND f0.symbol = 'applicable_dwa_standards' AND f0.active), $m${"title":"Weitere Regelwerke","columns":[{"key":"regelwerk","type":"text","label":"Regelwerk","placeholder":"z. B. FLL-Richtlinie, VDI-Richtlinie, Fachbuch"},{"key":"ausgabe","type":"text","label":"Ausgabe / Stand","placeholder":"z. B. 2023"},{"key":"anwendung","type":"text","label":"Anwendung im Projekt"}],"subtitle":"§6.2 · §6.3.2 — weitere technische Regelwerke außerhalb von DIN und DWA","add_label":"+ Regelwerk"}$m$::jsonb, NULL, NULL, 0, true
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id
 WHERE s.code = 'DWA-M-820-2' AND w.code = '820-2-04'
   AND NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'weitere_regelwerke');

-- ── ledger: md5 of every archived row as this block left it (the rollback restores only rows still in that state) ──
INSERT INTO m820_wa_written (tbl, id, md5) SELECT 'compliance_requirements', x.id, md5(row_to_json(x)::text) FROM compliance_requirements x WHERE x.id IN (SELECT id FROM compliance_requirements_archive_m820_wa) ON CONFLICT DO NOTHING;
INSERT INTO m820_wa_written (tbl, id, md5) SELECT 'fields', x.id, md5(row_to_json(x)::text) FROM fields x WHERE x.id IN (SELECT id FROM fields_archive_m820_wa) ON CONFLICT DO NOTHING;

COMMIT;
